const zone = document.querySelector("#zone");
zone.addEventListener("click", function (evenement) {
  const commande = evenement.target.closest("[data-atelier]");
  if (!commande || !zone.contains(commande)) { return; }
  document.querySelector("#choix").textContent = commande.dataset.atelier;
});

