const zone = document.querySelector("#commandes");
let nombre = 0;
let dernier = "Aucun choix";
function rendre() {
  document.querySelector("#nombre").textContent = nombre;
  document.querySelector("#dernier").textContent = dernier;
}
zone.addEventListener("click", function (evenement) {
  const commande = evenement.target.closest("[data-action]");
  if (!commande || !zone.contains(commande)) { return; }
  if (commande.dataset.action === "choisir") { nombre = nombre + 1; dernier = commande.dataset.titre; }
  else if (commande.dataset.action === "effacer") { nombre = 0; dernier = "Aucun choix"; }
  rendre();
});
rendre();

